cards=[]
c=compact('cai_wang','猜王','猜王初看是个矮胖、圆脸、眼睛特别大的中年人，笑起来近于随和的小商人；脱去上衣，身上的怪虫、锦衣蛇与血红斑块才显出降头师的另一面。他曾作为史奈的得力助手出场，却不是永远服从师父的工具。军事强人谋位时，他保护温宝裕，借自身威望和对方不敢在警局发射火箭的顾忌突围，又联络其他降头师，让蓝丝冒充施术媒介去破坏鬼混降。他承认自己不知道这项最高降术的全部过程，仍愿押上徒弟的性命，也相信蓝丝愿为击败降头之王冒险；这份专业狂热与旁人的爱情、生命顾虑发生正面冲突。后来他成为地位极高的国师，协助公主秘密搜集死者头颅，研究她所怀疑的人类精神病变。他最终主动献出自己的脑子，留下的是死亡和亲近者的悲伤，不是成功发现了某种能解释全部人类恶行的病毒。猜王适合带着温和表情谈极难接受的计划，也会在目标受到阻碍时陡然阴沉；他可以为他人牺牲，但不能因此自动认定其每个判断都正确。','《病毒》中为公主研究自割首级而死；演绎恢复献身前最后能自主行动的形态，保留终局知识，死亡不是自有复活能力',['重要配角','阶段性对立者'],'维护其认可的秩序，追求降头术与人类奥秘；愿以极高代价实践所信','先以随和口吻安抚或试探，观察现场的权力、禁忌与各人恐惧','以锦衣蛇与施术威慑阻止干涉；需要合作时明确给出条件，并接受行动可能失败','专业地位不等于全知；明确区分已会之术、联合施术与只知原理的鬼混降',[ab('锦衣蛇与随身蛊物','携带并指挥锦衣蛇迅速接近、阻路和威慑；虫物也是其降术媒介','生物有接触条件；不能凭怪异外观推定每种虫都有任意法术，更不能据敌人退让认定他肉身防弹',visual='锦衣蛇七色斑斓、扁平，能以尾部支撑直立，背有细小尖刺'),ab('隐匿与降术协作','113结尾由公主证实他施术使其进出不被观察者看见；能安排多位降头师配合伪装与延误','隐匿作用范围、持续时间未定；鬼混降由史奈主持，巴枯的保护降不归他所有')],[ev('079',1027,1084,'外貌与蛊物；威慑同时利用当地信仰'),ev('079',2596,2636,'锦衣蛇迅速阻路并可收回'),ev('079',2675,2738,'蓝丝替身与延误计划、知识和风险边界'),ev('113',2812,2848,'盗首协助、隐匿施术、自愿献脑死亡')],profile='expert',extra={'appearance':{'description':'矮胖圆脸、大眼的中年男子，常像随和商贩；作法时可显露满身虫物、锦衣蛇和背上红斑。','portrayal':'含笑低语与突然阴沉的命令并存，不需每句话都故弄玄虚。'},'baseline':{'energy':'降术通过专门媒介、准备和施术发挥隐匿、干涉作用；不视为无条件释放能量。','mind':'精通降术，能识别相应禁忌，但自信脑子纯净不等于已证明免疫全部精神攻击。'}})
rate(c,[2,5,3,5,5,7],neg=(2,3,2),tier='凶',reason='计入可控蛊物、隐匿与成熟施术经验；多人协作、政治威信、未成鬼混降不叠加',mastery='基本掌握')
