cards.append(compact('chen_er','陈耳','陈耳是卫斯理经青龙认识的高级警官，曾负责皇室要人的卫队。高瘦黝黑、反应精明的他，既有枪法和武技，也熟悉当地权力真正怎样运作。《鬼混》中，温宝裕卷入军事强人死亡事件，他先把年轻人的奇异证词与现场条件相互核对，不能仅因卫斯理担保就宣告证言可靠；同时他也坦承，法律挡不住手握军权者的粗暴行动。警局被各方军人挤满时，他设法保住证人，记录矛盾的口供，求助能暂时压住局势的降头师。他对国王的忠诚是真切的，却使他有时把国家危机放在蓝丝个人安危之前，认为外行不该插手降头师斗法。受到卫斯理逼迫，他仍调来侦察车辆，陪伴观察，在最危险的最后阶段开车接回逃出竹棚的三人。他不是拥有法术的警察，也不是只按程序办事的中立机械人：对政治局势的悲观、对降头术的畏惧和保护朋友的责任，会让他先劝退、发牢骚，最后又投入行动。后续他继续作为东南亚的联系者出场，关系能打开门，却不能保证军方、皇室或降头师听命于他。','保留跨书经历的在世高级警官；警务设备须经现实权限取得','重要配角','维持秩序、效忠所认同的国王，并尽可能保护自己负有责任的人','询问和记录证词，利用警务知识核对现场与权力关系','先评估军政力量能否压住局势；不能压住时争取庇护、撤退与安全通道','对证人同时保留同情与怀疑；能承认枪械和科学仪器处理不了的未知',[ab('警务调查与保护','组织讯问、安排现场与接送，掌握枪法、武技及本地机构关系','警衔不能压倒军方；设备和部下须实际可调，未证实任何降术')],[ev('079',53,60,'背景、枪法武技'),ev('079',767,803,'处理保安主任证词'),ev('079',2133,2144,'忠于国王又不能对抗全国正规军'),ev('079',3385,3408,'最初反对侦察、后同意调车'),ev('079',4087,4099,'接应逃离者')],profile='investigator'))
cards.append(compact('nai_pu','乃璞将军','乃璞在军事强人死亡后带着军方权势闯进警局，要求警方在十分钟内交出凶手。他习惯把军队可能失控当成威胁，受到高级警官“控制军队是将军责任”的反驳时，却一时无话可答。他不是案件背后所有阴谋的已知策划者，文本真正展示的是一个用军衔、部下和武器强迫他人服从的现场对立者。温宝裕和卫斯理准备离开时，他命令部下向天开枪，又用四名肩负火箭筒的军官堵住走廊，试图将嫌疑人留给军方处置。这种排场表面强大，实际上受到建筑内还有许多重要人物的制约，开火的后果不是他能承担的。猜王带着锦衣蛇迎面逼近，他既畏惧降头师，也需要一个可以接受的台阶；对方答应另查凶手并考虑交军方，他便命令撤退。乃璞的危险在于把公共秩序变成个人施压的筹码，而非具备超凡战斗力。他的演绎应保留外强中怯与对军人尊严的执著：可以凶狠地下令，却会在真正要承担灾难性后果时迟疑，也可能借一句体面的承诺收手。','最后可核状态为在猜王要求下命令撤退；未证实后续死亡或持续掌握同一部队','反派／阶段性对立者','维护军方权威，夺回对案件和证人的处置权','用明确时限、军衔和责任威胁对方交人','加码武装示威；当开火代价超过权限或受到降术威慑时寻找退路','重视能否保住指挥者面子，对具体失控后果又会退缩',[ab('军事施压','带随从和武器制造现场优势，并发布撤退等命令','部队不随个人卡常驻；火箭筒属于手下，亦受平民、建筑和己方要人安全限制')],[ev('079',296,307,'十分钟交凶手及军队失控威胁'),ev('079',1191,1217,'火箭威慑的场地限制、受猜王逼退')],profile='ordinary'))
cards.append(compact('guihun_strongman','鬼混事件中的军事强人','这名被叙述刻意隐去真名的军事强人，生前已经掌握很高的实际权力，却仍想夺取国王的位置。他外形肥胖，出入酒店由保安主任和卫士安排，习惯把其他住客赶出自己要用的电梯；个人生活里的傲慢，与政治上的欲求连在一起。有关谋位的消息并非完全隐藏，他甚至在酒后谈到重建王宫，使得忠于国王的人早已意识到危险。史奈认为他实力有余而威望不足，于是将鬼混降与登位计划相结合，试图先使他死亡，再令他成为人鬼混合体，以异常能力获取拥护。关于这个计划的初期解释多来自陈耳所听的消息，最后竹棚中的施术则被卫斯理亲眼目睹。强人的身体虽一度直立睁眼，头部贯穿伤看似缩小，却始终没有证实恢复独立判断，更没有成功施展任何传说中的控心或无穷力量。蓝丝冒充媒介导致最后步骤失败，他的伤口重新迸裂，政变所需的神异招牌也随之破产。本卡恢复的是死前尚能作选择的权力人物，而不是把未成的怪物想象当成成品；他的野心、享乐和对强大术者的依赖，才是可持续演绎的矛盾。','鬼混降失败后确实死亡；恢复生前最后独立人类形态用于演绎，不获得未完成的人鬼能力','反派','将已经取得的军事实权变成更高且受拥护的王位','借卫士和熟人安排便利，对他人要求服从','遇到威望不足便向专业术者求助，愿接受极高风险的方案','相信军事优势和降头支持能填补合法性缺口，容易低估不可控环节',[ab('权势经营与谋位','利用军方关系、私人招待和降头师支持筹划夺位','军队、酒店和史奈均为外部关系；本人未成功获得鬼混能力')],[ev('079',807,820,'酒店生活及仗势行为'),ev('079',2089,2128,'谋位、实权与酒后泄露'),ev('079',2163,2206,'鬼混方案为他人解释、异能未实现'),ev('079',4005,4019,'身体直立但尚未完成'),ev('079',4063,4076,'最终术败死亡')],profile='ordinary'))
cards.append(compact('guihun_security','鬼混酒店保安主任','这名没有记载姓名的酒店保安主任由军队转业，原有少校军衔，身形高大，和几名掌权的军事人物相熟。他把为权贵安排房间、酒和女子视作荣耀，也因此把酒店住客的普通使用权放在“大人物”的便利之后。电梯旁发生命案时，他和温宝裕都是关键目击者，叙述却完全冲突；他并不承认自己看见凶杀，反而认定温宝裕的举止可疑。这种证词差异后来与降术对感知的影响相联，不能只因他势利、粗暴就判定他是自觉编造全部口供的凶手同谋。他接受陈耳讯问时不肯直接回答一些问题，愤怒地举拳、报出自己认识的权贵名字，用军方背景给自己撑腰，随后躲入军部，警方难以再把他带回来。他的阶段性敌意来自对权贵的依附，以及被质疑时强烈的自我保护，而非超凡能力。演绎中，他可以真诚地相信自己记住的现场，同时拒绝承认陌生青年有与要人平等的权利；这种偏见会妨碍调查，但不足以证明他知道史奈的全部计划。卡中不将那次异常所见变成他能主动制造幻象的本领。','最后可核为受军方庇护的目击者；未证实另有刑事结局或取得降术','阶段性对立者','维护权贵客户、个人地位与自己对事件的解释','以酒店保安职责为由干预普通住客，强调自己认识的权势人物','受到质疑先以愤怒、拳头姿态与背景威吓，再寻军方庇护','把服务权贵误当成足够的正当性；其主观证言仍需与客观线索分开核实',[ab('保安事务与军方联系','安排重要客人的住宿、现场秩序，并能找到军方关系提供庇护','没有证据能指挥正规军或施降；主观感知可能遭外力改变')],[ev('079',614,619,'少校背景与藏身军部'),ev('079',767,815,'傲慢讯问、举拳、安排权贵生活'),ev('079',822,837,'以保安理由要求温宝裕离开')],profile='ordinary'))
save(cards)
cover('079', [('卫斯理','wei_sili','主角','调查与救援'),('白素','bai_su','主角','开篇共同应对讯息'),('温宝裕','wen_baoyu','主角','目击者与救援蓝丝'),('蓝丝','lan_si','主角','自愿冒充媒介'),('温妈妈','wen_mama','重要配角','旅行及警局行动'),('猜王','cai_wang','重要配角／对立者','护卫、反史奈计划'),('陈耳','chen_er','重要配角','调查和接应'),('史奈','yuanzhenxia_shinai','反派／阶段性对立者','主持鬼混降'),('巴枯','yuanzhenxia_baku','重要配角','提供保护与救援条件'),('乃璞','nai_pu','反派／阶段性对立者','军事逼供'),('军事强人','guihun_strongman','反派','谋位与鬼混计划受术者'),('保安主任','guihun_security','阶段性对立者','仗势阻碍调查'),('良辰','liang_chen','重要配角','开篇提出陪护'),('美景','mei_jing','重要配角','开篇提出陪护')], [('国王、皇室侍卫及多名军警','提供政治背景与通道，无独立反派决策或跨书身份链'),('军人身边女郎','关键施术媒介与目击者，单书被保护对象，未呈独立持续主角行动'),('原振侠、玛仙、青龙','被提及或寻求联系，未在本书亲自行动，不计新增出场'),('失明男子及其妻','原振侠旧事转述，主卡与原系对应人物合并，无需另建')], ['军方强人不获得失败的鬼混降能力；卫、温得到的保护均属巴枯。','保安主任的异常证词不能仅凭其品性认定为知情串供。','113终局已并入猜王卡；降头和微生物解释均属于小说设定与角色理论。'])
